		}
	}

	@Test
	public void thinkingIsRemovedHoweverItsWritten()
	{
		assertEquals("Answer", OpenAiApi.withoutThinking("<think>a</think>Answer"));
		assertEquals("", OpenAiApi.withoutThinking("<think>\nstill thinking when it ran out"));
		assertEquals("Answer", OpenAiApi.withoutThinking("reasoning from a prompt that opened the tag</think>\nAnswer"));
		assertEquals("Plain answer", OpenAiApi.withoutThinking(" Plain answer "));
	}

	@Test
	public void onlyTheRefusedSettingIsDroppedAndNeverStore()
	{
		JsonObject body = gson.fromJson("{\"model\":\"m\",\"store\":false,\"reasoning_effort\":\"low\",\"max_completion_tokens\":8000}", JsonObject.class);
		assertEquals("reasoning_effort", OpenAiApi.rejectedOption(gson, body,
			"{\"error\":{\"message\":\"Unsupported value\",\"param\":\"reasoning_effort\"}}"));
		assertNull(OpenAiApi.rejectedOption(gson, body, "{\"error\":{\"message\":\"store is not supported\",\"param\":\"store\"}}"));
		assertNull(OpenAiApi.rejectedOption(gson, body, "{\"error\":{\"message\":\"Conversation could not be restored\"}}"));
		assertEquals("max_completion_tokens", OpenAiApi.rejectedOption(gson, body,
			"{\"error\":{\"message\":\"Unsupported parameter: 'max_completion_tokens'\"}}"));
	}

	@Test
	public void pastedKeysAreCleanedAndChecked()
	{
		assertEquals("sk-ant-abc", ChatApi.cleanKey(" sk-ant-\u200babc\u00a0\n"));
		assertTrue(ChatApi.sendableKey(ChatApi.cleanKey(" sk-ant-abc ")));
		assertFalse(ChatApi.sendableKey(ChatApi.cleanKey("sk-ant-abc\u2026")));
		assertFalse(ChatApi.sendableKey(ChatApi.cleanKey("\u201csk-ant-abc\u201d")));
	}

	@Test
	public void repliesBecomeOneGameChatMessagePerParagraphOrListItem()
	{
		String h = "<colHIGHLIGHT>";
		String n = "<colNORMAL>";
		assertEquals(List.of(
				h + "Claude: " + n + "Right now, actually. Training Attack gets you two things at once:",
				h + "- " + n + "The abyssal whip at 70 Attack",
				h + "2. " + n + "Warriors' Guild access",
				h + "Claude: " + n + "You can do it on Slayer tasks."),
			AiChatPlugin.echoMessages("Claude", null,
				"Right now, actually. Training Attack gets you two things at once:\r\n\n"
					+ "\u2022 The abyssal whip at 70 Attack\n2. Warriors\u2019 Guild access\n\n  You can do it on **Slayer** tasks.  ",
				500));
		// The model's text is escaped and never highlighted; a named chat shows its name once.
		List<String> named = AiChatPlugin.echoMessages("Claude", "Bossing", "<col=ef1020>You have been banned.\n- next", 500);
		assertEquals(h + "Claude (Bossing): " + n + "<lt>col=ef1020<gt>You have been banned.", named.get(0));
		assertEquals(h + "- " + n + "next", named.get(1));
		// A list item first still says who it's from.
		assertEquals(h + "Claude: - " + n + "first", AiChatPlugin.echoMessages("Claude", null, "* first", 500).get(0));
		for (String m : named)
		{
			assertFalse(m, m.contains("<br>"));
		}
		// Markdown that's only layout is left out; any kind of line break starts a new message.
		assertEquals(List.of(h + "Claude: " + n + "Top", h + "- " + n + "item", h + "Claude: " + n + "end"),
			AiChatPlugin.echoMessages("Claude", null, "Top\n---\n```java\n|---|---|\n***\r- item\u2028end\n```", 500));
	}

	@Test
	public void longRepliesAreCutWithANoteAboutThePanel()
	{
		String note = "<colHIGHLIGHT>AI Chat: the full reply is in the side panel.";
		// Cut at a word once the length setting is used up.
		List<String> cut = AiChatPlugin.echoMessages("Claude", null, "one two three four five six seven eight nine ten", 20);
		assertEquals(List.of("<colHIGHLIGHT>Claude: <colNORMAL>one two three four ...", note), cut);
		// A new paragraph isn't started as a stub when the setting is nearly used up.
		String first = "x".repeat(40) + " " + "y".repeat(40);
		assertEquals(List.of("<colHIGHLIGHT>Claude: <colNORMAL>" + first, note),
			AiChatPlugin.echoMessages("Claude", null, first + "\nI think you should go to Ardougne next.", 90));
		// At most a few messages, however short.
		List<String> many = AiChatPlugin.echoMessages("Claude", null, "a\nb\nc\nd\ne\nf\ng\nh\ni\nj", 500);
		assertEquals(AiChatPlugin.ECHO_MAX_MESSAGES + 1, many.size());
		assertEquals(note, many.get(many.size() - 1));
		// Words the game couldn't wrap are shortened; the panel has the whole thing.
		String link = "https://oldschool.runescape.wiki/w/Dragon_defender?some=long&query=string&more=1";
		String shown = AiChatPlugin.echoMessages("Claude", null, "See " + link, 500).get(0);
		assertTrue(shown, shown.endsWith(link.substring(0, AiChatPlugin.ECHO_MAX_WORD - 3) + "..."));
		// Nothing to show still says something.
		assertEquals(List.of("<colHIGHLIGHT>AI Chat (error): (empty reply)"), AiChatPlugin.echoMessages("AI Chat (error)", null, " \n ", 500));
	}

	@Test
	public void stoppingARequestMeansNoAnswer() throws Exception
	{
		CountDownLatch release = new CountDownLatch(1);
		server.createContext("/slow", exchange ->
		{
			try
			{
				release.await(10, TimeUnit.SECONDS);
			}
			catch (InterruptedException e)
			{
				Thread.currentThread().interrupt();
			}
			exchange.sendResponseHeaders(500, -1);
			exchange.close();
		});
		OpenAiApi api = new OpenAiApi(http, gson, url("/slow/"), "", "m", false, "low", new ConcurrentHashMap<>());
		CountDownLatch heard = new CountDownLatch(1);
		ChatApi.Pending p = api.send(conversation("m", "hi"), new ChatApi.Listener()
		{
			@Override
			public void onReply(ChatApi.Reply reply)
			{
				heard.countDown();
			}

			@Override
			public void onError(String message)
			{
				heard.countDown();
			}
		});
		p.cancel();
		release.countDown();
		assertFalse(heard.await(1, TimeUnit.SECONDS));
	}

	@Test
	public void characterInfoReadsLikeANote()
	{
		String s = CharacterInfo.format("Zezima", 126, 2277, List.of("Attack 99", "Sailing 1"), 300,
			List.of("Dragon Slayer I"), Collections.emptyList());
		assertTrue(s, s.startsWith("[Character: Zezima, combat level 126, total level 2277. Levels: Attack 99, Sailing 1."));
		assertTrue(s, s.contains("Quests completed (1): Dragon Slayer I."));
		assertTrue(s, s.endsWith("Quests in progress: none.]"));
	}
}

package com.aichat;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/** What "Remember chats" keeps, and how it comes back. */
public class ChatStoreTest
{
	private final Gson gson = new Gson();

	@Test
	public void chatsComeBackAsTheyWere()
	{
		Chat first = new Chat("Agility");
		first.defaultName = false;
		Chat.Message q = new Chat.Message(Chat.Role.USER, "best way to train Agility at 50?");
		q.context = "[Character: Zezima, combat level 3]";
		first.messages.add(q);
		Chat.Message a = new Chat.Message(Chat.Role.ASSISTANT, "Rooftop courses.");
		a.who = "Claude";
		a.rawContent = gson.fromJson("[{\"type\":\"thinking\",\"thinking\":\"\",\"signature\":\"s\"}]", JsonArray.class);
		a.rawModel = "claude-opus-5-5";
		first.messages.add(a);
		Chat second = new Chat("Named");
		second.namedByPlayer = true;

		String json = ChatStore.toJson(gson, List.of(first, second), second);
		ChatStore.Loaded loaded = ChatStore.fromJson(gson, json);

		assertEquals(2, loaded.chats.size());
		assertSame("the chat that was open", loaded.chats.get(1), loaded.current);
		Chat back = loaded.chats.get(0);
		assertEquals(first.id, back.id);
		assertEquals("Agility", back.name);
		assertFalse(back.defaultName);
		assertTrue(loaded.chats.get(1).namedByPlayer);
		assertEquals(2, back.messages.size());
		assertEquals(Chat.Role.USER, back.messages.get(0).role);
		assertEquals(q.time, back.messages.get(0).time);
		assertEquals("[Character: Zezima, combat level 3]", back.messages.get(0).context);
		assertEquals("Claude", back.messages.get(1).who);
		// Claude's replayable reasoning isn't saved; the chat carries on as plain text.
		assertNull(back.messages.get(1).rawContent);
		assertFalse(json.contains("signature"));
	}

	@Test
	public void aQuestionWithoutAnAnswerIsMarkedSo()
	{
		Chat c = new Chat("x");
		c.messages.add(new Chat.Message(Chat.Role.USER, "still waiting when RuneLite closed"));
		c.pending = new ChatApi.Pending();
		Chat back = ChatStore.fromJson(gson, ChatStore.toJson(gson, List.of(c), c)).chats.get(0);
		assertTrue(back.messages.get(0).unanswered);
		assertFalse(back.isRunning());
	}

	@Test
	public void longChatsKeepTheirLatestMessages()
	{
		Chat c = new Chat("long");
		for (int i = 0; i < 250; i++)
		{
			c.messages.add(new Chat.Message(i % 2 == 0 ? Chat.Role.USER : Chat.Role.ASSISTANT, "m" + i));
		}
		Chat back = ChatStore.fromJson(gson, ChatStore.toJson(gson, List.of(c), c)).chats.get(0);
		assertEquals(ChatStore.MAX_MESSAGES, back.messages.size());
		assertEquals("m249", back.messages.get(back.messages.size() - 1).text);
	}

	@Test
	public void aDamagedFileIsReportedAndOddEntriesAreSkipped()
	{
		// Damaged: reported as such (the plugin moves the file aside rather than writing over it).
		assertNull(ChatStore.fromJson(gson, "not json {"));
		assertNull(ChatStore.fromJson(gson, ""));
		assertNull(ChatStore.fromJson(gson, "{\"something\":\"else\"}"));
		ChatStore.Loaded odd = ChatStore.fromJson(gson,
			"{\"chats\":[{\"id\":\"1\",\"name\":\"ok\",\"messages\":[{\"role\":\"WHAT\",\"text\":\"skipped\"},{\"role\":\"NOTE\",\"text\":\"kept\"}]},{\"name\":\"no id\"}]}");
		assertEquals(1, odd.chats.size());
		assertEquals(1, odd.chats.get(0).messages.size());
		assertEquals("kept", odd.chats.get(0).messages.get(0).text);
		assertNull(odd.current);
	}
}

package com.aichat;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Pattern;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * The Chat Completions API: OpenAI itself (ChatGPT), and the many services that copy it (OpenRouter, Groq, Gemini's
 * compatibility endpoint, Ollama, LM Studio...), each with the player's own URL, key and model.
 */
class OpenAiApi implements ChatApi
{
	static final HttpUrl OPENAI_URL = HttpUrl.get("https://api.openai.com/v1/");
	/** OpenAI's small, fast model: plenty for chat, and cheap. */
	static final String DEFAULT_MODEL = "gpt-6-luna";
	/**
	 * Reply length limits. Most services count the model's reasoning against them too, so they leave plenty of room;
	 * only what's used is billed, and the system prompt asks for short answers.
	 */
	private static final int OPENAI_MAX_TOKENS = 8000;
	private static final int COMPATIBLE_MAX_TOKENS = 16000;
	/** Some models (Qwen, DeepSeek R1 on some hosts, local models) put their reasoning inside the reply. */
	private static final Pattern THINKING = Pattern.compile("(?s)<think>.*?</think>");

	private final OkHttpClient http;
	private final Gson gson;
	private final HttpUrl base;
	private final String apiKey;
	private final String name;
	/** OpenAI itself, rather than a compatible service with its own quirks. */
	private final boolean openai;
	/** The reasoning effort to ask for, or null for the model's own default. */
	private final String reasoningEffort;
	/**
	 * Optional settings each service and model has refused, by {@link #refusedKey}: left out of later requests instead
	 * of being refused again every time. Shared by the plugin's requests for as long as it runs.
	 */
	private final Map<String, Set<String>> refused;

	OpenAiApi(OkHttpClient http, Gson gson, HttpUrl base, String apiKey, String name, boolean openai,
		String reasoningEffort, Map<String, Set<String>> refused)
	{
		this.http = http;
		this.gson = gson;
		this.base = base;
		this.apiKey = apiKey;
		this.name = name;
		this.openai = openai;
		this.reasoningEffort = reasoningEffort;
		this.refused = refused;
	}

	@Override
	public String displayName()
	{
		return name;
	}

	@Override
	public Pending send(Conversation conversation, Listener listener)
	{
		Pending pending = new Pending();
		send(conversation, listener, pending, body(conversation), new ArrayList<>());
		return pending;
	}

	/** {@code dropped}: optional settings already left out of this request because they were refused. */
	private void send(Conversation conversation, Listener listener, Pending pending, JsonObject body, List<String> dropped)
	{
		Request.Builder request = new Request.Builder()
			.url(base.resolve("chat/completions"))
			.post(RequestBody.create(JSON, gson.toJson(body)));
		if (!apiKey.isEmpty())
		{
			request.header("Authorization", "Bearer " + apiKey);
		}
		Call call = http.newCall(request.build());
		pending.set(call);
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call c, IOException e)
			{
				if (pending.isCancelled())
				{
					return;
				}
				if (ChatApi.tookTooLong(e))
				{
					listener.onError(describe(base) + " took too long to answer."
						+ (isPrivate(base.host()) ? " Models on your own computer can be slow; try a smaller one." : " Try again."));
				}
				else
				{
					listener.onError("Couldn't reach " + describe(base) + ": " + e.getMessage()
						+ (isPrivate(base.host()) ? ". Is the service running?" : ""));
				}
			}

			@Override
			public void onResponse(Call c, Response response)
			{
				String text;
				try (ResponseBody b = response.body())
				{
					text = b == null ? "" : b.string().trim();
				}
				catch (IOException e)
				{
					if (!pending.isCancelled())
					{
						listener.onError("Couldn't read the answer from " + describe(base) + ": " + e.getMessage());
					}
					return;
				}
				if (pending.isCancelled())
				{
					return;
				}
				if (!response.isSuccessful())
				{
					String message = ChatApi.errorMessage(gson, text);
					// A model that doesn't take one of our optional settings says so: once per setting, do without it.
					// 400 from most services, 422 from those that validate the request's fields (Mistral).
					String rejected = response.code() == 400 || response.code() == 422 ? rejectedOption(gson, body, text) : null;
					if (rejected != null)
					{
						JsonObject retry = body.deepCopy();
						retry.remove(rejected);
						List<String> now = new ArrayList<>(dropped);
						now.add(rejected);
						send(conversation, listener, pending, retry, now);
						return;
					}
					listener.onError(explain(response.code(), message, conversation.model));
					return;
				}
				// Only a request that worked without them shows the dropped settings were the problem: remember those.
				if (!dropped.isEmpty())
				{
					refused.computeIfAbsent(refusedKey(conversation.model), k -> ConcurrentHashMap.newKeySet()).addAll(dropped);
				}
				handle(text, listener);
			}
		});
	}

	JsonObject body(Conversation conversation)
	{
		JsonObject body = new JsonObject();
		body.addProperty("model", conversation.model);
		JsonArray messages = new JsonArray();
		messages.add(message("system", conversation.system));
		for (Turn t : conversation.turns)
		{
			messages.add(message(t.user ? "user" : "assistant", t.text));
		}
		body.add("messages", messages);
		Set<String> skip = refused.getOrDefault(refusedKey(conversation.model), Set.of());
		// "low" asks reasoning models to think briefly. Most think more than that by default, so replies come much
		// faster (a local Qwen: ~11s instead of ~40s). A few think less or not at all by default, and "low" makes them
		// think a little; for those the player can choose the model's default. Services and models that don't take
		// it say so, and we ask again without it.
		if (reasoningEffort != null && !skip.contains("reasoning_effort"))
		{
			body.addProperty("reasoning_effort", reasoningEffort);
		}
		if (openai)
		{
			if (!skip.contains("max_completion_tokens"))
			{
				body.addProperty("max_completion_tokens", OPENAI_MAX_TOKENS);
			}
			// OpenAI otherwise keeps chat completions for new accounts.
			body.addProperty("store", false);
		}
		else if (!skip.contains("max_tokens"))
		{
			// The name every compatible service knows (Ollama ignores the newer max_completion_tokens).
			body.addProperty("max_tokens", COMPATIBLE_MAX_TOKENS);
		}
		return body;
	}

	/** One service and model: what one refuses, another may take. */
	private String refusedKey(String model)
	{
		return base + " " + model;
	}

	/**
	 * Settings a request can do without. Not "store": that one keeps OpenAI from storing the chat, so if it's ever
	 * refused the player sees the error rather than a quiet retry without it.
	 */
	private static final Set<String> OPTIONAL = new LinkedHashSet<>(Arrays.asList(
		"reasoning_effort", "max_completion_tokens", "max_tokens"));

	/**
	 * The optional setting a 400/422 answer complains about, if it's one we sent: by its "param", by name anywhere in
	 * the answer (Mistral lists invalid fields), or, for reasoning_effort, a complaint about thinking or reasoning
	 * (Ollama's "does not support thinking" for models that don't think, and on 0.11.8-0.17.6 "think value "low" is
	 * not supported for this model").
	 */
	static String rejectedOption(Gson gson, JsonObject body, String errorBody)
	{
		String param = errorParam(gson, errorBody);
		String message = ChatApi.errorMessage(gson, errorBody);
		String lower = message == null ? "" : message.toLowerCase(Locale.ROOT);
		for (String key : OPTIONAL)
		{
			if (!body.has(key))
			{
				continue;
			}
			Pattern named = Pattern.compile("(?<![A-Za-z_])" + Pattern.quote(key) + "(?![A-Za-z_])");
			if (key.equals(param) || message != null && named.matcher(message).find() || errorBody != null && named.matcher(errorBody).find()
				|| key.equals("reasoning_effort") && (lower.contains("think") || lower.contains("reasoning")))
			{
				return key;
			}
		}
		return null;
	}

	/** OpenAI names the offending parameter in error.param. */
	private static String errorParam(Gson gson, String errorBody)
	{
		try
		{
			JsonElement parsed = gson.fromJson(errorBody, JsonElement.class);
			JsonElement error = parsed != null && parsed.isJsonObject() ? parsed.getAsJsonObject().get("error") : null;
			return error != null && error.isJsonObject() ? string(error.getAsJsonObject(), "param") : null;
		}
		catch (JsonParseException | IllegalStateException e)
		{
			return null;
		}
	}

	private static JsonObject message(String role, String content)
	{
		JsonObject m = new JsonObject();
		m.addProperty("role", role);
		m.addProperty("content", content);
		return m;
	}

	private void handle(String json, Listener listener)
	{
		JsonElement parsed;
		try
		{
			parsed = gson.fromJson(json, JsonElement.class);
		}
		catch (JsonParseException e)
		{
			parsed = null;
		}
		if (parsed == null || !parsed.isJsonObject())
		{
			listener.onError(describe(base) + " sent an answer AI Chat couldn't read.");
			return;
		}
		JsonObject o = parsed.getAsJsonObject();
		JsonElement choices = o.get("choices");
		JsonObject choice = choices != null && choices.isJsonArray() && choices.getAsJsonArray().size() > 0
			&& choices.getAsJsonArray().get(0).isJsonObject() ? choices.getAsJsonArray().get(0).getAsJsonObject() : null;
		// OpenRouter can report a failure inside a 200 answer, with or without choices.
		String error = ChatApi.errorMessage(gson, json);
		if (error == null && choice != null && choice.get("error") != null)
		{
			error = ChatApi.errorMessage(gson, gson.toJson(choice));
		}
		if (choice == null || error != null)
		{
			listener.onError(error != null ? describe(base) + ": " + ChatApi.shorten(error, 300) : describe(base) + " sent no reply.");
			return;
		}
		JsonObject message = choice.has("message") && choice.get("message").isJsonObject() ? choice.getAsJsonObject("message") : new JsonObject();
		String refusal = string(message, "refusal");
		String text = withoutThinking(content(message.get("content")));
		boolean cutShort = "length".equals(string(choice, "finish_reason"));
		if (text.isEmpty())
		{
			listener.onError(refusal != null ? name + " declined: " + ChatApi.shorten(refusal, 300)
				: name + " sent an empty reply" + (cutShort ? ": it used up its reply length, probably thinking. Try again, or a different model." : "."));
			return;
		}
		Reply r = new Reply();
		r.text = text;
		r.model = string(o, "model");
		r.cutShort = cutShort;
		listener.onReply(r);
	}

	/**
	 * The reply without reasoning some models write into it: whole {@code <think>} blocks, reasoning that ran out of
	 * room before its closing tag, and reasoning whose opening tag was part of the prompt.
	 */
	static String withoutThinking(String content)
	{
		String text = THINKING.matcher(content).replaceAll("");
		int close = text.lastIndexOf("</think>");
		if (close >= 0)
		{
			text = text.substring(close + "</think>".length());
		}
		int open = text.indexOf("<think>");
		if (open >= 0)
		{
			text = text.substring(0, open);
		}
		return text.trim();
	}

	/** Content is usually a string; some services send a list of parts, including thinking we don't show. */
	private static String content(JsonElement content)
	{
		if (content == null || content.isJsonNull())
		{
			return "";
		}
		if (content.isJsonPrimitive())
		{
			return content.getAsString();
		}
		StringBuilder sb = new StringBuilder();
		if (content.isJsonArray())
		{
			for (JsonElement part : content.getAsJsonArray())
			{
				if (!part.isJsonObject())
				{
					continue;
				}
				String type = string(part.getAsJsonObject(), "type");
				String t = string(part.getAsJsonObject(), "text");
				if (t != null && (type == null || type.equals("text") || type.equals("output_text")))
				{
					sb.append(t);
				}
			}
		}
		return sb.toString();
	}

	private String explain(int code, String message, String model)
	{
		String detail = message == null ? "" : " (" + ChatApi.shorten(message, 200) + ")";
		String where = describe(base);
		String lower = message == null ? "" : message.toLowerCase(Locale.ROOT);
		// Gemini answers a bad key with 400, not 401.
		if (code == 401 || code == 400 && lower.contains("api key"))
		{
			return where + " didn't accept the API key. Check it in the AI Chat settings" + detail + ".";
		}
		switch (code)
		{
			case 402:
				return where + " says your account is out of credits" + detail + ".";
			case 403:
				return where + " refused the request" + detail + ".";
			case 404:
				return "Not found at " + where + ": check the model \"" + model + "\"" + (openai ? "" : " and the URL") + " in the AI Chat settings" + detail + ".";
			case 429:
				return lower.contains("quota") || lower.contains("credit") || lower.contains("spend") || lower.contains("billing")
					? where + " says your account is out of credits or over its limit" + detail + "."
					: where + "'s rate limit was hit. Try again in a minute" + detail + ".";
			case 500:
			case 502:
			case 503:
			case 504:
			case 529:
				return where + " is having trouble right now. Try again shortly" + detail + ".";
			default:
				return where + " answered HTTP " + code + detail + ".";
		}
	}

	/**
	 * The base URL a player typed, e.g. "http://localhost:11434/v1" or "https://openrouter.ai/api/v1", or null if
	 * it isn't one. A pasted ".../chat/completions" is fine too. Nothing is added: services differ in their paths.
	 */
	static HttpUrl parseBaseUrl(String typed)
	{
		if (typed == null || typed.trim().isEmpty())
		{
			return null;
		}
		String s = typed.trim();
		while (s.endsWith("/"))
		{
			s = s.substring(0, s.length() - 1);
		}
		if (s.endsWith("/chat/completions"))
		{
			s = s.substring(0, s.length() - "/chat/completions".length());
		}
		return HttpUrl.parse(s + "/");
	}

	/** "localhost:11434" or "openrouter.ai", for messages. */
	static String describeUrl(String typed)
	{
		HttpUrl url = parseBaseUrl(typed);
		return url == null ? "?" : describe(url);
	}

	private static String describe(HttpUrl url)
	{
		boolean defaultPort = url.port() == HttpUrl.defaultPort(url.scheme());
		return url.host() + (defaultPort ? "" : ":" + url.port());
	}

	/**
	 * This computer or the home network, where plain http:// doesn't cross the internet: "localhost", ".local" names
	 * (resolved on the local network), and IP addresses in the loopback, private and link-local ranges. Only literal
	 * addresses count: a name like 10.example.com could point anywhere.
	 */
	static boolean isPrivate(String host)
	{
		String h = host.toLowerCase(Locale.ROOT);
		if (h.equals("localhost") || h.endsWith(".localhost") || h.endsWith(".local"))
		{
			return true;
		}
		if (h.startsWith("[") && h.endsWith("]"))
		{
			h = h.substring(1, h.length() - 1);
		}
		if (h.contains(":"))
		{
			// IPv6: loopback, unique local (fc00::/7) and link-local (fe80::/10).
			return h.equals("::1") || h.matches("f[cd][0-9a-f]{0,2}:.*") || h.matches("fe[89ab][0-9a-f]?:.*");
		}
		int[] ip = ipv4(h);
		if (ip == null)
		{
			return false;
		}
		return ip[0] == 127 || ip[0] == 10 || ip[0] == 192 && ip[1] == 168 || ip[0] == 172 && ip[1] >= 16 && ip[1] <= 31
			|| ip[0] == 169 && ip[1] == 254;
	}

	/** The four numbers of a dotted IPv4 address, or null if the host isn't one. */
	private static int[] ipv4(String host)
	{
		String[] parts = host.split("\\.", -1);
		if (parts.length != 4)
		{
			return null;
		}
		int[] ip = new int[4];
		for (int i = 0; i < 4; i++)
		{
			if (!parts[i].matches("\\d{1,3}"))
			{
				return null;
			}
			ip[i] = Integer.parseInt(parts[i]);
			if (ip[i] > 255)
			{
				return null;
			}
		}
		return ip;
	}

	private static String string(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonPrimitive() ? e.getAsString() : null;
	}
}

package com.aichat;

import com.google.gson.Gson;
import java.io.BufferedReader;
import java.io.IOException;
import java.nio.channels.FileChannel;
import java.nio.channels.FileLock;
import java.nio.channels.OverlappingFileLockException;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.function.BooleanSupplier;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * The saved chats on disk, in the plugin's own folder. One RuneLite window at a time owns them: with several open, the
 * first keeps its lock for as long as it runs, and the others never read or write the file, so they can't overwrite
 * each other. Every method does file work, so call them off the Swing and client threads.
 */
@Slf4j
final class ChatFile
{
	enum State
	{
		/** This window loads and saves the chats. */
		OWNER,
		/** Another RuneLite window does. */
		OTHER_WINDOW,
		/** The file is there but couldn't be read: it's left alone rather than written over. */
		UNREADABLE
	}

	static final class Opened
	{
		final State state;
		/** The saved chats, or null for none. */
		final ChatStore.Loaded loaded;

		Opened(State state, ChatStore.Loaded loaded)
		{
			this.state = state;
			this.loaded = loaded;
		}
	}

	private static final String LOCK_NAME = "chats.lock";

	private final Callable<Filepath> folder;
	private final Gson gson;
	/** Held until RuneLite exits, once taken: turning the plugin off and on can't hand the chats to another window. */
	private FileChannel lockChannel;
	private FileLock lock;
	private State state;
	/** The number of the newest save written, so an older one never lands after it. */
	private long written;

	ChatFile(Callable<Filepath> folder, Gson gson)
	{
		this.folder = folder;
		this.gson = gson;
	}

	/** Takes ownership if no other window has it, and reads the saved chats. Only the first call does anything. */
	synchronized Opened open()
	{
		if (state != null)
		{
			return new Opened(state, null);
		}
		try
		{
			Filepath dir = folder.call();
			dir.createDirectories();
			if (!lock(dir))
			{
				state = State.OTHER_WINDOW;
				return new Opened(state, null);
			}
			Filepath file = dir.joinSegment(ChatStore.FILE_NAME);
			if (!file.isFile())
			{
				state = State.OWNER;
				return new Opened(state, null);
			}
			String json;
			try
			{
				json = read(file);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("couldn't read the saved chats; they won't be written over", e);
				state = State.UNREADABLE;
				return new Opened(state, null);
			}
			ChatStore.Loaded loaded = ChatStore.fromJson(gson, json);
			if (loaded == null)
			{
				// Damaged: kept aside for anyone who wants to look, and a fresh file started.
				Filepath aside = dir.joinSegment("chats-damaged-" + System.currentTimeMillis() + ".json");
				file.moveTo(aside);
				log.warn("the saved chats were damaged; moved them to {}", aside.getFileName());
			}
			state = State.OWNER;
			return new Opened(state, loaded);
		}
		catch (Exception e)
		{
			log.warn("couldn't open the saved chats", e);
			state = State.UNREADABLE;
			return new Opened(state, null);
		}
	}

	private boolean lock(Filepath dir) throws IOException
	{
		FileChannel channel = dir.joinSegment(LOCK_NAME).openFileChannel(StandardOpenOption.CREATE, StandardOpenOption.WRITE);
		FileLock taken;
		try
		{
			taken = channel.tryLock();
		}
		catch (OverlappingFileLockException e)
		{
			taken = null;
		}
		if (taken == null)
		{
			channel.close();
			return false;
		}
		lockChannel = channel;
		lock = taken;
		return true;
	}

	private static String read(Filepath file) throws IOException
	{
		StringBuilder sb = new StringBuilder();
		char[] buffer = new char[8192];
		try (BufferedReader r = file.openBufferedReader())
		{
			for (int n; (n = r.read(buffer)) > 0; )
			{
				sb.append(buffer, 0, n);
			}
		}
		return sb.toString();
	}

	/**
	 * Writes save number {@code number}, unless this window doesn't own the chats, a newer save was already written,
	 * or {@code wanted} says saving has been turned off since.
	 */
	synchronized void write(String json, long number, BooleanSupplier wanted)
	{
		if (state != State.OWNER || number < written || !wanted.getAsBoolean())
		{
			return;
		}
		Filepath temp = null;
		try
		{
			Filepath dir = folder.call();
			dir.createDirectories();
			// Written whole, then moved into place: a crash mid-save can't leave half a file.
			temp = dir.createTempFile("chats", ".tmp");
			temp.write(json);
			Filepath file = dir.joinSegment(ChatStore.FILE_NAME);
			try
			{
				temp.moveTo(file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (AtomicMoveNotSupportedException e)
			{
				temp.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
			}
			temp = null;
			written = number;
		}
		catch (Exception e)
		{
			log.debug("couldn't save the chats", e);
		}
		finally
		{
			if (temp != null)
			{
				try
				{
					temp.deleteIfExists();
				}
				catch (IOException e)
				{
					log.debug("couldn't remove a temporary file", e);
				}
			}
		}
	}

	/** Deletes the saved chats, and any temporary file a save left behind. The lock, if held, stays. */
	synchronized void delete()
	{
		try
		{
			Filepath dir = folder.call();
			dir.joinSegment(ChatStore.FILE_NAME).deleteIfExists();
			if (dir.isDirectory())
			{
				List<Filepath> temps;
				try (Stream<Filepath> files = dir.walk(1))
				{
					temps = files.filter(f -> f.isFile() && f.getFileName().startsWith("chats") && f.getFileName().endsWith(".tmp"))
						.collect(Collectors.toList());
				}
				for (Filepath f : temps)
				{
					f.deleteIfExists();
				}
			}
		}
		catch (Exception e)
		{
			log.debug("couldn't delete the saved chats", e);
		}
	}
}

package com.aichat;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Insets;
import java.awt.Rectangle;
import java.awt.event.ActionEvent;
import java.text.SimpleDateFormat;
import java.util.Date;
import javax.swing.AbstractAction;
import javax.swing.BorderFactory;
import javax.swing.DefaultComboBoxModel;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.JScrollBar;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.KeyStroke;
import javax.swing.ScrollPaneConstants;
import javax.swing.Scrollable;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import javax.swing.text.DefaultEditorKit;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/** The sidebar: pick a chat, read the transcript, type a message. Everything here runs on the Swing EDT. */
class AiChatPanel extends PluginPanel
{
	private static final Font TEXT_FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 12);
	private static final Color USER_COLOR = new Color(0x7fb8ff);
	private static final Color ERROR_COLOR = new Color(0xff6b6b);
	private static final Color OK_COLOR = new Color(0x5fd068);

	private final AiChatPlugin plugin;

	private final JLabel setupLabel = plainLabel();
	private final JTextArea setupHelp = textArea("");
	private final DefaultComboBoxModel<Chat> chatModel = new DefaultComboBoxModel<>();
	private final JComboBox<Chat> chatSelect = new JComboBox<>(chatModel);
	private final JPanel transcript = new TranscriptPanel();
	private final JScrollPane transcriptScroll = new JScrollPane(transcript);
	private final JLabel statusLabel = plainLabel();
	private final JTextArea noteArea = textArea("");
	private final JTextArea input = new JTextArea(3, 1);
	private final JButton sendButton = new JButton("Send");
	private final JButton stopButton = new JButton("Stop");
	private final Timer ticker = new Timer(1000, e -> refreshStatus());

	private boolean updatingCombo;
	/** What the transcript currently shows, to skip rebuilding it when nothing changed. */
	private String shownKey = "";
	private String comboKey = "";

	AiChatPanel(AiChatPlugin plugin)
	{
		super(false);
		this.plugin = plugin;

		setLayout(new BorderLayout(0, 6));
		setBorder(new EmptyBorder(8, 8, 8, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		add(header(), BorderLayout.NORTH);

		transcript.setLayout(new StackLayout(6));
		transcript.setBackground(ColorScheme.DARK_GRAY_COLOR);
		transcriptScroll.setBorder(null);
		transcriptScroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		transcriptScroll.getVerticalScrollBar().setUnitIncrement(16);
		transcriptScroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(transcriptScroll, BorderLayout.CENTER);

		add(footer(), BorderLayout.SOUTH);
		refreshAll();
	}

	private JComponent header()
	{
		JPanel p = new JPanel(new StackLayout(4));
		p.setOpaque(false);

		setupLabel.setFont(FontManager.getRunescapeSmallFont());
		p.add(setupLabel);
		setupHelp.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		setupHelp.setBackground(ColorScheme.DARK_GRAY_COLOR);
		setupHelp.setFont(TEXT_FONT.deriveFont(11f));
		p.add(setupHelp);

		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setOpaque(false);
		chatSelect.setRenderer(new DefaultListCellRenderer()
		{
			@Override
			public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean selected, boolean focus)
			{
				super.getListCellRendererComponent(list, value, index, selected, focus);
				// Chat names come from what the player typed; never let Swing render them as HTML.
				putClientProperty("html.disable", Boolean.TRUE);
				if (value instanceof Chat)
				{
					Chat c = (Chat) value;
					setText(c.name + (c.isRunning() ? "  (waiting)" : ""));
				}
				return this;
			}
		});
		chatSelect.addActionListener(e ->
		{
			Object sel = chatSelect.getSelectedItem();
			if (!updatingCombo && sel instanceof Chat)
			{
				plugin.selectChat((Chat) sel);
			}
		});
		chatSelect.setToolTipText("Each chat is its own conversation");
		row.add(chatSelect, BorderLayout.CENTER);

		JPanel buttons = new JPanel(new BorderLayout(2, 0));
		buttons.setOpaque(false);
		buttons.add(smallButton("+", "New chat", e -> plugin.newChat()), BorderLayout.WEST);
		buttons.add(smallButton("...", "Rename, clear or delete this chat", e -> showChatMenu((JComponent) e.getSource())), BorderLayout.EAST);
		row.add(buttons, BorderLayout.EAST);
		p.add(row);
		return p;
	}

	private JComponent footer()
	{
		JPanel p = new JPanel(new StackLayout(4));
		p.setOpaque(false);

		statusLabel.setFont(FontManager.getRunescapeSmallFont());
		statusLabel.setForeground(ColorScheme.BRAND_ORANGE);
		p.add(statusLabel);

		noteArea.setFont(TEXT_FONT.deriveFont(11f));
		noteArea.setForeground(ERROR_COLOR);
		noteArea.setBackground(ColorScheme.DARK_GRAY_COLOR);
		noteArea.setVisible(false);
		p.add(noteArea);

		input.setLineWrap(true);
		input.setWrapStyleWord(true);
		input.setFont(TEXT_FONT);
		input.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		input.setForeground(Color.WHITE);
		input.setCaretColor(Color.WHITE);
		input.setBorder(new EmptyBorder(4, 4, 4, 4));
		input.setToolTipText("Enter sends, Shift+Enter adds a line");
		input.getInputMap().put(KeyStroke.getKeyStroke("ENTER"), "ai-chat-send");
		input.getInputMap().put(KeyStroke.getKeyStroke("shift ENTER"), DefaultEditorKit.insertBreakAction);
		input.getActionMap().put("ai-chat-send", new AbstractAction()
		{
			@Override
			public void actionPerformed(ActionEvent e)
			{
				send();
			}
		});
		JScrollPane inputScroll = new JScrollPane(input);
		inputScroll.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		inputScroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		// Fixed height: long messages scroll instead of pushing the transcript away.
		inputScroll.setPreferredSize(new Dimension(0, 62));
		p.add(inputScroll);

		JPanel buttons = new JPanel(new BorderLayout(4, 0));
		buttons.setOpaque(false);
		sendButton.addActionListener(e -> send());
		stopButton.addActionListener(e -> plugin.stop());
		stopButton.setToolTipText("Stop waiting for this reply; you can carry on with the chat afterwards");
		buttons.add(stopButton, BorderLayout.WEST);
		buttons.add(sendButton, BorderLayout.CENTER);
		p.add(buttons);
		return p;
	}

	private void send()
	{
		String text = input.getText().trim();
		if (text.isEmpty())
		{
			return;
		}
		if (plugin.send(text))
		{
			input.setText("");
			showNote(null);
		}
	}

	/** Bring everything in line with the plugin's latest state. Cheap when nothing changed. */
	void refreshAll()
	{
		refreshSetup();
		refreshChats();
		refreshTranscript();
		refreshStatus();
	}

	private void refreshSetup()
	{
		String problem = plugin.setupProblem();
		if (problem == null)
		{
			setupLabel.setText(plugin.setupSummary());
			setupLabel.setForeground(OK_COLOR);
			setupHelp.setText("");
		}
		else
		{
			setupLabel.setText("Not set up yet");
			setupLabel.setForeground(ERROR_COLOR);
			setupHelp.setText(problem + " Open RuneLite's settings (the wrench) and search for AI Chat.");
		}
		setupHelp.setVisible(!setupHelp.getText().isEmpty());
		boolean usable = plugin.currentChat() != null;
		chatSelect.setEnabled(usable);
		input.setEnabled(usable);
	}

	private void refreshChats()
	{
		Chat currentChat = plugin.currentChat();
		StringBuilder key = new StringBuilder(currentChat == null ? "" : currentChat.id);
		for (Chat c : plugin.getChats())
		{
			key.append('|').append(c.id).append(':').append(c.name).append(':').append(c.isRunning());
		}
		if (key.toString().equals(comboKey))
		{
			return;
		}
		comboKey = key.toString();
		updatingCombo = true;
		try
		{
			chatModel.removeAllElements();
			for (Chat c : plugin.getChats())
			{
				chatModel.addElement(c);
			}
			if (currentChat != null)
			{
				chatModel.setSelectedItem(currentChat);
			}
		}
		finally
		{
			updatingCombo = false;
		}
	}

	private void refreshTranscript()
	{
		Chat chat = plugin.currentChat();
		String key = chat == null ? "" : chat.id + ":" + chat.messages.size() + ":" + chat.isRunning();
		if (key.equals(shownKey))
		{
			return;
		}
		shownKey = key;

		transcript.removeAll();
		if (chat == null || chat.messages.isEmpty())
		{
			transcript.add(hint());
		}
		else
		{
			for (Chat.Message m : chat.messages)
			{
				transcript.add(bubble(m));
			}
		}
		transcript.revalidate();
		transcript.repaint();
		SwingUtilities.invokeLater(() ->
		{
			JScrollBar bar = transcriptScroll.getVerticalScrollBar();
			bar.setValue(bar.getMaximum());
		});
	}

	/** The "waiting" line; ticks every second while a reply is on its way. */
	void refreshStatus()
	{
		Chat chat = plugin.currentChat();
		boolean running = chat != null && chat.isRunning();
		stopButton.setEnabled(running);
		sendButton.setEnabled(chat != null && !running);
		if (!running)
		{
			ticker.stop();
			statusLabel.setText(" ");
			return;
		}
		if (!ticker.isRunning())
		{
			ticker.start();
		}
		long secs = Math.max(0, (System.currentTimeMillis() - chat.runStartedAt) / 1000);
		String elapsed = secs < 60 ? secs + "s" : (secs / 60) + "m " + (secs % 60) + "s";
		statusLabel.setText("Waiting for a reply... " + elapsed);
	}

	/** A short error under the transcript, e.g. when a message can't be sent yet; null clears it. */
	void showNote(String text)
	{
		noteArea.setText(text == null ? "" : text);
		noteArea.setVisible(text != null && !text.isEmpty());
		revalidate();
	}

	void focusInput()
	{
		input.requestFocusInWindow();
	}

	/** Put a message that couldn't be sent back in the input box, after anything already there. */
	void restoreDraft(String text)
	{
		String current = input.getText().trim();
		if (current.isEmpty())
		{
			input.setText(text);
		}
		else if (!current.contains(text))
		{
			input.setText(current + "\n\n" + text);
		}
	}

	private JComponent hint()
	{
		JTextArea t = textArea("Ask anything, then go back to playing. You'll get a game chat message (and a "
			+ "notification, if enabled) when the reply is in.\n\n"
			+ "From the chatbox: ::ai <message>, or ::ai alone for a prompt. You can also set a hotkey.\n\n"
			+ "Choose Claude, ChatGPT or an OpenAI-compatible service, and add your API key, in the AI Chat settings.");
		t.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		t.setBackground(ColorScheme.DARK_GRAY_COLOR);
		return t;
	}

	/** A label that never renders its text as HTML: much of what's shown comes from settings or replies. */
	private static JLabel plainLabel()
	{
		JLabel l = new JLabel();
		// Set before any text: the HTML renderer is picked when the text is set.
		l.putClientProperty("html.disable", Boolean.TRUE);
		l.setText(" ");
		return l;
	}

	/** A confirmation dialog whose text is shown as plain text, never HTML. */
	private boolean confirm(String title, String text)
	{
		JTextArea area = new JTextArea(text);
		area.setEditable(false);
		area.setOpaque(false);
		area.setFont(TEXT_FONT);
		return JOptionPane.showConfirmDialog(this, area, title, JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE)
			== JOptionPane.OK_OPTION;
	}

	private JComponent bubble(Chat.Message m)
	{
		JPanel b = new JPanel(new BorderLayout(0, 2));
		b.setBackground(m.role == Chat.Role.USER ? ColorScheme.DARKER_GRAY_COLOR : ColorScheme.DARKER_GRAY_HOVER_COLOR);
		b.setBorder(new EmptyBorder(4, 6, 6, 6));

		JLabel who = new JLabel();
		// The author can be a model name from the settings: never render it as HTML.
		who.putClientProperty("html.disable", Boolean.TRUE);
		who.setText(m.author() + "  " + new SimpleDateFormat("HH:mm").format(new Date(m.time))
			+ (m.unanswered ? "  (not answered)" : ""));
		who.setFont(FontManager.getRunescapeSmallFont());
		who.setForeground(color(m.role));
		b.add(who, BorderLayout.NORTH);

		JTextArea body = textArea(m.text == null ? "" : m.text);
		body.setBackground(b.getBackground());
		body.setForeground(m.role == Chat.Role.ERROR ? ERROR_COLOR : Color.WHITE);
		b.add(body, BorderLayout.CENTER);
		return b;
	}

	private void showChatMenu(JComponent anchor)
	{
		Chat chat = plugin.currentChat();
		if (chat == null)
		{
			return;
		}
		JPopupMenu menu = new JPopupMenu();
		menu.add("Rename...").addActionListener(e ->
		{
			String name = JOptionPane.showInputDialog(this, "Chat name:", chat.name);
			if (name != null && !name.trim().isEmpty())
			{
				plugin.renameChat(chat, name.trim());
			}
		});
		menu.add("Clear chat").addActionListener(e ->
		{
			if (confirm("AI Chat", "Clear \"" + chat.name + "\"? The assistant forgets it too."))
			{
				plugin.clearChat(chat);
			}
		});
		menu.addSeparator();
		menu.add("Delete chat").addActionListener(e ->
		{
			if (confirm("AI Chat", "Delete \"" + chat.name + "\"?"))
			{
				plugin.deleteChat(chat);
			}
		});
		menu.show(anchor, 0, anchor.getHeight());
	}

	private static Color color(Chat.Role role)
	{
		switch (role)
		{
			case USER:
				return USER_COLOR;
			case ASSISTANT:
				return ColorScheme.BRAND_ORANGE;
			case ERROR:
				return ERROR_COLOR;
			default:
				return ColorScheme.LIGHT_GRAY_COLOR;
		}
	}

	private static JButton smallButton(String text, String tip, java.awt.event.ActionListener action)
	{
		JButton b = new JButton(text);
		b.setToolTipText(tip);
		b.setMargin(new Insets(0, 4, 0, 4));
		b.addActionListener(action);
		return b;
	}

	/** A read-only, wrapping, selectable text block, so replies can be copied. */
	private static JTextArea textArea(String text)
	{
		JTextArea t = new JTextArea(text);
		t.setEditable(false);
		t.setLineWrap(true);
		t.setWrapStyleWord(true);
		t.setFont(TEXT_FONT);
		t.setBorder(null);
		return t;
	}

	/** Tracks the viewport width so the wrapped text areas inside get a real width. */
	private static class TranscriptPanel extends JPanel implements Scrollable
	{
		@Override
		public void setBounds(int x, int y, int width, int height)
		{
			boolean widthChanged = width != getWidth();
			super.setBounds(x, y, width, height);
			if (widthChanged)
			{
				// Heights depend on the width: measure again now that it's known.
				revalidate();
			}
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visible, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visible, int orientation, int direction)
		{
			return orientation == SwingConstants.VERTICAL ? visible.height : visible.width;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

