package com.aichat;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarPlayerID;

/** The character details sent with a message when the player turns that on. */
final class CharacterInfo
{
	private CharacterInfo()
	{
	}

	/** Client thread only: reading quest states runs a game script. Null when there's no character to describe. */
	static String describe(Client client)
	{
		Player me = client.getLocalPlayer();
		if (me == null || me.getName() == null)
		{
			return null;
		}
		List<String> levels = new ArrayList<>();
		for (Skill s : Skill.values())
		{
			// Skill also lists the deprecated total-level pseudo-skill; the total is reported on its own below.
			if (!"OVERALL".equals(s.name()))
			{
				levels.add(s.getName() + " " + client.getRealSkillLevel(s));
			}
		}
		List<String> done = new ArrayList<>();
		List<String> started = new ArrayList<>();
		for (Quest q : Quest.values())
		{
			QuestState state = q.getState(client);
			if (state == QuestState.FINISHED)
			{
				done.add(q.getName());
			}
			else if (state == QuestState.IN_PROGRESS)
			{
				started.add(q.getName());
			}
		}
		return format(me.getName(), me.getCombatLevel(), client.getTotalLevel(), levels,
			client.getVarpValue(VarPlayerID.QP), done, started);
	}

	static String format(String name, int combat, int total, List<String> levels, int questPoints, List<String> done, List<String> started)
	{
		return "[Character: " + name + ", combat level " + combat + ", total level " + total + ". "
			+ "Levels: " + String.join(", ", levels) + ". "
			+ "Quest points: " + questPoints + ". "
			+ "Quests completed (" + done.size() + "): " + (done.isEmpty() ? "none" : String.join(", ", done)) + ". "
			+ "Quests in progress: " + (started.isEmpty() ? "none" : String.join(", ", started)) + ".]";
	}
}

package com.aichat;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.ArrayList;
import java.util.List;

/**
 * What's kept of the chats between RuneLite sessions, when "Remember chats" is on: names and messages, nothing else.
 * API keys aren't part of a chat, and Claude's replayable reasoning stays in memory only. Converting happens on the
 * Swing EDT (where chats live); reading and writing the file happen elsewhere.
 */
final class ChatStore
{
	static final String FILE_NAME = "chats.json";
	/** Older messages of a long chat aren't kept. */
	static final int MAX_MESSAGES = 200;

	private ChatStore()
	{
	}

	static final class Saved
	{
		int version = 1;
		String current;
		/** Null in a file that isn't ours. */
		List<SavedChat> chats;
	}

	static final class SavedChat
	{
		String id;
		String name;
		boolean defaultName;
		boolean namedByPlayer;
		List<SavedMessage> messages = new ArrayList<>();
	}

	static final class SavedMessage
	{
		String role;
		String text;
		long time;
		String who;
		String context;
		boolean unanswered;
	}

	/** EDT. */
	static String toJson(Gson gson, List<Chat> chats, Chat current)
	{
		Saved saved = new Saved();
		saved.current = current == null ? null : current.id;
		saved.chats = new ArrayList<>();
		for (Chat c : chats)
		{
			SavedChat sc = new SavedChat();
			sc.id = c.id;
			sc.name = c.name;
			sc.defaultName = c.defaultName;
			sc.namedByPlayer = c.namedByPlayer;
			List<Chat.Message> messages = c.messages.subList(Math.max(0, c.messages.size() - MAX_MESSAGES), c.messages.size());
			for (Chat.Message m : messages)
			{
				SavedMessage sm = new SavedMessage();
				sm.role = m.role.name();
				sm.text = m.text;
				sm.time = m.time;
				sm.who = m.who;
				sm.context = m.context;
				// A question still waiting when RuneLite closes won't be answered.
				sm.unanswered = m.unanswered || c.isRunning() && m.role == Chat.Role.USER && m == lastUserMessage(c);
				sc.messages.add(sm);
			}
			saved.chats.add(sc);
		}
		return gson.toJson(saved);
	}

	static final class Loaded
	{
		final List<Chat> chats = new ArrayList<>();
		/** The chat that was open, if it's among them. */
		Chat current;
	}

	/** The chats in a saved file, in their order, or null if the file is damaged (not JSON, or not ours). */
	static Loaded fromJson(Gson gson, String json)
	{
		Loaded loaded = new Loaded();
		Saved saved;
		try
		{
			saved = gson.fromJson(json, Saved.class);
		}
		catch (JsonParseException | IllegalStateException e)
		{
			return null;
		}
		if (saved == null || saved.chats == null)
		{
			return null;
		}
		for (SavedChat sc : saved.chats)
		{
			if (sc == null || sc.id == null || sc.name == null)
			{
				continue;
			}
			Chat c = new Chat(sc.id, sc.name);
			c.defaultName = sc.defaultName;
			c.namedByPlayer = sc.namedByPlayer;
			if (sc.messages != null)
			{
				for (SavedMessage sm : sc.messages)
				{
					Chat.Role role = role(sm == null ? null : sm.role);
					if (role == null || sm.text == null)
					{
						continue;
					}
					Chat.Message m = new Chat.Message(role, sm.text, sm.time);
					m.who = sm.who;
					m.context = sm.context;
					m.unanswered = sm.unanswered;
					c.messages.add(m);
				}
			}
			// The last question never got its answer if nothing came after it.
			if (!c.messages.isEmpty() && c.messages.get(c.messages.size() - 1).role == Chat.Role.USER)
			{
				c.messages.get(c.messages.size() - 1).unanswered = true;
			}
			loaded.chats.add(c);
			if (sc.id.equals(saved.current))
			{
				loaded.current = c;
			}
		}
		return loaded;
	}

	private static Chat.Role role(String name)
	{
		if (name == null)
		{
			return null;
		}
		for (Chat.Role r : Chat.Role.values())
		{
			if (r.name().equals(name))
			{
				return r;
			}
		}
		return null;
	}

	private static Chat.Message lastUserMessage(Chat c)
	{
		for (int i = c.messages.size() - 1; i >= 0; i--)
		{
			if (c.messages.get(i).role == Chat.Role.USER)
			{
				return c.messages.get(i);
			}
		}
		return null;
	}
}

package com.aichat;

import com.google.gson.JsonArray;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

/** One conversation in the panel. Kept in memory while the plugin runs. Only touched on the Swing EDT. */
class Chat
{
	enum Role
	{
		USER, ASSISTANT, NOTE, ERROR
	}

	static class Message
	{
		final Role role;
		final String text;
		final long time;
		/** Who wrote an ASSISTANT reply: "Claude", "ChatGPT", or the model of an OpenAI-compatible service. */
		String who;
		/** Character details sent along with this USER message, if any. Part of what the provider saw. */
		String context;
		/** A USER message whose request failed or was stopped. Left out of later requests. */
		boolean unanswered;
		/**
		 * Anthropic only: the reply's content blocks exactly as returned, with the model and system prompt that
		 * produced them. Claude expects them back unchanged on the next turn, as long as nothing before them changed.
		 */
		JsonArray rawContent;
		String rawModel;
		String rawSystem;

		Message(Role role, String text)
		{
			this(role, text, System.currentTimeMillis());
		}

		Message(Role role, String text, long time)
		{
			this.role = role;
			this.text = text;
			this.time = time;
		}

		String author()
		{
			switch (role)
			{
				case USER:
					return "You";
				case ASSISTANT:
					return who != null ? who : "Assistant";
				case ERROR:
					return "Error";
				default:
					return "Note";
			}
		}
	}

	final String id;
	String name;
	/** Whether {@link #name} was made up by us, so the first message can replace it with something better. */
	boolean defaultName = true;
	/** The player named this chat themselves, so the name can appear in notifications (it isn't their question). */
	boolean namedByPlayer;
	final List<Message> messages = new ArrayList<>();

	/** The request in flight, or null. */
	ChatApi.Pending pending;
	long runStartedAt;

	Chat(String name)
	{
		this(UUID.randomUUID().toString(), name);
	}

	/** A chat brought back from {@link ChatStore}. */
	Chat(String id, String name)
	{
		this.id = id;
		this.name = name;
	}

	boolean isRunning()
	{
		return pending != null;
	}
}

package com.aichat;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import javax.swing.JTextArea;
import net.runelite.client.ui.PluginPanel;

/**
 * Stacks visible children top to bottom at the container's full width. Unlike BoxLayout, each child's height is
 * asked for at that width, so wrapping text areas get the right height on the first layout instead of one line.
 */
class StackLayout implements LayoutManager
{
	/** Width to assume before the sidebar has been laid out: the panel minus AiChatPanel's border. */
	private static final int FALLBACK_WIDTH = PluginPanel.PANEL_WIDTH + PluginPanel.SCROLLBAR_WIDTH - 16;

	private final int gap;

	StackLayout(int gap)
	{
		this.gap = gap;
	}

	@Override
	public void addLayoutComponent(String name, Component comp)
	{
	}

	@Override
	public void removeLayoutComponent(Component comp)
	{
	}

	@Override
	public Dimension preferredLayoutSize(Container parent)
	{
		Insets in = parent.getInsets();
		int outer = parent.getWidth() > 0 ? parent.getWidth() : FALLBACK_WIDTH;
		int w = Math.max(0, outer - in.left - in.right);
		int h = in.top + in.bottom;
		int n = 0;
		for (Component c : parent.getComponents())
		{
			if (c.isVisible())
			{
				h += heightFor(c, w);
				n++;
			}
		}
		if (n > 1)
		{
			h += gap * (n - 1);
		}
		return new Dimension(outer, h);
	}

	@Override
	public Dimension minimumLayoutSize(Container parent)
	{
		return preferredLayoutSize(parent);
	}

	@Override
	public void layoutContainer(Container parent)
	{
		Insets in = parent.getInsets();
		int w = Math.max(0, parent.getWidth() - in.left - in.right);
		int y = in.top;
		for (Component c : parent.getComponents())
		{
			if (!c.isVisible())
			{
				continue;
			}
			int h = heightFor(c, w);
			c.setBounds(in.left, y, w, h);
			y += h + gap;
		}
	}

	/** Preferred height of {@code c} when it is {@code w} wide. */
	static int heightFor(Component c, int w)
	{
		if (c instanceof JTextArea)
		{
			// A wrapped text area computes its preferred height from its current size.
			c.setSize(w, Short.MAX_VALUE);
		}
		else if (c instanceof Container)
		{
			// Lay the children out at this width first, so nested text areas know theirs.
			c.setSize(w, Short.MAX_VALUE);
			((Container) c).doLayout();
		}
		return c.getPreferredSize().height;
	}
}

package com.aichat;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.InterruptedIOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import okhttp3.Call;
import okhttp3.MediaType;

/** An AI provider: send the conversation so far, get back one reply or one error. */
interface ChatApi
{
	MediaType JSON = MediaType.get("application/json; charset=utf-8");

	/**
	 * Starts the request; the listener hears back later on an OkHttp thread, exactly once, unless the request is
	 * cancelled first (then not at all).
	 */
	Pending send(Conversation conversation, Listener listener);

	/** The provider's name for this setup, shown as the author of its replies. */
	String displayName();

	final class Conversation
	{
		String model;
		String system;
		final List<Turn> turns = new ArrayList<>();
	}

	/** One turn of the conversation as the provider sees it. */
	final class Turn
	{
		final boolean user;
		final String text;
		/** Anthropic only: the reply's content blocks as returned, see {@link Chat.Message#rawContent}. */
		JsonArray rawContent;
		String rawModel;
		String rawSystem;

		Turn(boolean user, String text)
		{
			this.user = user;
			this.text = text;
		}
	}

	final class Reply
	{
		String text;
		/** The model that answered, which can differ from the one asked for (e.g. a fallback). */
		String model;
		/** The reply hit the length limit. */
		boolean cutShort;
		JsonArray rawContent;
		/**
		 * Anthropic only: earlier replies had to be sent as plain text for this one (see AnthropicApi). They can't be
		 * sent any other way from now on, or this reply's reasoning wouldn't match what it was built on.
		 */
		boolean historyAsText;
	}

	interface Listener
	{
		void onReply(Reply reply);

		/** A short, readable explanation for the panel. */
		void onError(String message);
	}

	/** A request in flight. A retry replaces the call inside, so cancelling always stops whatever is running. */
	final class Pending
	{
		private volatile Call call;
		private volatile boolean cancelled;

		void set(Call c)
		{
			call = c;
			if (cancelled)
			{
				c.cancel();
			}
		}

		void cancel()
		{
			cancelled = true;
			Call c = call;
			if (c != null)
			{
				c.cancel();
			}
		}

		boolean isCancelled()
		{
			return cancelled;
		}
	}

	/**
	 * The error message inside a provider's error body, or null. Anthropic, OpenAI and most others send
	 * {"error":{"message":...}}; Gemini wraps that in a list, some local servers send {"error":"text"}, Mistral
	 * {"detail":...}. The body is read whatever its Content-Type says: OpenAI labels some JSON errors as plain text.
	 */
	static String errorMessage(Gson gson, String body)
	{
		try
		{
			JsonElement parsed = gson.fromJson(body, JsonElement.class);
			if (parsed != null && parsed.isJsonArray() && parsed.getAsJsonArray().size() > 0)
			{
				parsed = parsed.getAsJsonArray().get(0);
			}
			if (parsed == null || !parsed.isJsonObject())
			{
				return null;
			}
			JsonObject o = parsed.getAsJsonObject();
			JsonElement error = o.get("error");
			if (error != null && error.isJsonObject())
			{
				JsonElement message = error.getAsJsonObject().get("message");
				return message != null && message.isJsonPrimitive() ? message.getAsString() : null;
			}
			if (error != null && error.isJsonPrimitive())
			{
				return error.getAsString();
			}
			JsonElement detail = o.get("detail");
			if (detail != null && detail.isJsonPrimitive())
			{
				return detail.getAsString();
			}
			return null;
		}
		catch (JsonParseException | IllegalStateException | ClassCastException | UnsupportedOperationException e)
		{
			return null;
		}
	}

	/**
	 * A pasted API key without what copying tends to add: spaces, line breaks, non-breaking and zero-width spaces.
	 */
	static String cleanKey(String key)
	{
		return key == null ? "" : key.replaceAll("[\\s\\p{Z}\\p{Cf}]", "");
	}

	/** Whether a (cleaned) key can go in an HTTP header: printable ASCII only, so no curly quotes or ellipses. */
	static boolean sendableKey(String key)
	{
		for (int i = 0; i < key.length(); i++)
		{
			char c = key.charAt(i);
			if (c < 0x21 || c > 0x7e)
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * The provider was reached but took too long to answer. A connect timeout is a different story: nothing answered.
	 */
	static boolean tookTooLong(IOException e)
	{
		if (!(e instanceof InterruptedIOException))
		{
			return false;
		}
		String m = e.getMessage();
		return m == null || !m.toLowerCase(Locale.ROOT).contains("connect");
	}

	/** Cut to a length that fits the panel. */
	static String shorten(String s, int max)
	{
		if (s == null)
		{
			return "";
		}
		String t = s.trim();
		return t.length() <= max ? t : t.substring(0, max).trim() + "...";
	}
}

package com.aichat;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/** Claude, through Anthropic's Messages API with the player's own API key. */
@Slf4j
class AnthropicApi implements ChatApi
{
	static final HttpUrl URL = HttpUrl.get("https://api.anthropic.com/v1/messages");
	/** Room for a full answer; replies are billed by what's used, and the system prompt asks for short ones. */
	private static final int MAX_TOKENS = 16000;
	/**
	 * Models that take server-side fallback: when their safety filter declines a request, Anthropic retries it on
	 * another Claude model instead of refusing outright.
	 */
	private static final Set<String> FALLBACK_MODELS = Set.of("claude-fable-5-1", "claude-opus-5-5", "claude-opus-5", "claude-sonnet-5-5");
	private static final String FALLBACK_BETA = "server-side-fallback-2026-07-01";

	private final OkHttpClient http;
	private final Gson gson;
	private final HttpUrl url;
	private final String apiKey;

	AnthropicApi(OkHttpClient http, Gson gson, HttpUrl url, String apiKey)
	{
		this.http = http;
		this.gson = gson;
		this.url = url;
		this.apiKey = apiKey;
	}

	@Override
	public String displayName()
	{
		return "Claude";
	}

	@Override
	public Pending send(Conversation request, Listener callback)
	{
		Pending pending = new Pending();
		send(request, callback, pending, true, FALLBACK_MODELS.contains(request.model));
		return pending;
	}

	/**
	 * {@code replay}: send earlier replies back as they came. {@code fallback}: ask for server-side fallback. Each is
	 * dropped once if Anthropic refuses it.
	 */
	private void send(Conversation request, Listener callback, Pending pending, boolean replay, boolean fallback)
	{
		String model = request.model;
		Request.Builder http = new Request.Builder()
			.url(url)
			.header("x-api-key", apiKey)
			.header("anthropic-version", "2023-06-01")
			.post(RequestBody.create(JSON, gson.toJson(body(request, replay, fallback))));
		if (fallback)
		{
			http.header("anthropic-beta", FALLBACK_BETA);
		}
		Call call = this.http.newCall(http.build());
		pending.set(call);
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call c, IOException e)
			{
				if (!pending.isCancelled())
				{
					callback.onError(ChatApi.tookTooLong(e)
						? "Claude took too long to answer. Try again, maybe with a shorter question or a faster model."
						: "Couldn't reach Anthropic: " + e.getMessage());
				}
			}

			@Override
			public void onResponse(Call c, Response response)
			{
				String text;
				try (ResponseBody body = response.body())
				{
					text = body == null ? "" : body.string();
				}
				catch (IOException e)
				{
					if (!pending.isCancelled())
					{
						callback.onError("Couldn't read Anthropic's answer: " + e.getMessage());
					}
					return;
				}
				if (pending.isCancelled())
				{
					return;
				}
				if (!response.isSuccessful())
				{
					String message = ChatApi.errorMessage(gson, text);
					// The fallback beta was retired or isn't enabled for this account: do without it.
					if (fallback && response.code() == 400 && message != null
						&& (message.contains("anthropic-beta") || message.contains("fallbacks")))
					{
						log.debug("retrying without server-side fallback: {}", message);
						send(request, callback, pending, replay, false);
						return;
					}
					// Claude checks that the reasoning it's given back belongs to this exact conversation; after a
					// settings change it may not. Once, carry on without it.
					if (replay && response.code() == 400 && message != null && message.contains("thinking"))
					{
						log.debug("retrying without earlier reasoning: {}", message);
						send(request, callback, pending, false, fallback);
						return;
					}
					callback.onError(explain(response.code(), message, model));
					return;
				}
				handle(text, callback, !replay);
			}
		});
	}

	/** The request body. {@code replay}: send earlier replies back as they came, reasoning included, where allowed. */
	JsonObject body(Conversation request, boolean replay, boolean fallback)
	{
		JsonObject body = new JsonObject();
		body.addProperty("model", request.model);
		body.addProperty("max_tokens", MAX_TOKENS);
		body.addProperty("system", request.system);
		JsonArray messages = new JsonArray();
		for (Turn t : request.turns)
		{
			JsonObject m = new JsonObject();
			m.addProperty("role", t.user ? "user" : "assistant");
			// Only unchanged: same model, same instructions (the plugin drops rawContent if earlier turns changed).
			if (replay && t.rawContent != null && request.model.equals(t.rawModel) && request.system.equals(t.rawSystem))
			{
				m.add("content", t.rawContent);
			}
			else
			{
				m.addProperty("content", t.text);
			}
			messages.add(m);
		}
		body.add("messages", messages);
		if (fallback)
		{
			body.addProperty("fallbacks", "default");
		}
		return body;
	}

	private void handle(String json, Listener callback, boolean historyAsText)
	{
		JsonObject o;
		try
		{
			o = gson.fromJson(json, JsonObject.class);
		}
		catch (JsonParseException e)
		{
			callback.onError("Anthropic sent an answer AI Chat couldn't read.");
			return;
		}
		if (o == null)
		{
			callback.onError("Anthropic sent an empty answer.");
			return;
		}
		String stop = string(o, "stop_reason");
		JsonArray content = o.has("content") && o.get("content").isJsonArray() ? o.getAsJsonArray("content") : new JsonArray();
		StringBuilder text = new StringBuilder();
		for (JsonElement block : content)
		{
			if (block.isJsonObject() && "text".equals(string(block.getAsJsonObject(), "type")))
			{
				String t = string(block.getAsJsonObject(), "text");
				if (t != null)
				{
					text.append(t);
				}
			}
		}
		if ("refusal".equals(stop))
		{
			callback.onError("Claude declined to answer that.");
			return;
		}
		if (text.toString().trim().isEmpty())
		{
			callback.onError("Claude sent an empty reply" + (stop == null ? "." : " (" + stop + ")."));
			return;
		}
		Reply r = new Reply();
		r.text = text.toString().trim();
		r.model = string(o, "model");
		r.cutShort = "max_tokens".equals(stop);
		r.rawContent = content;
		r.historyAsText = historyAsText;
		callback.onReply(r);
	}

	private static String explain(int code, String message, String model)
	{
		String detail = message == null ? "" : " (" + ChatApi.shorten(message, 200) + ")";
		switch (code)
		{
			case 401:
				return "Anthropic didn't accept your API key. Check \"Claude API key\" in the AI Chat settings.";
			case 402:
				return "Anthropic says there's a billing problem with your account" + detail + ".";
			case 403:
				return "Your Anthropic API key isn't allowed to do that" + detail + ".";
			case 404:
				return "The Claude model \"" + model + "\" isn't available to your key. Check \"Claude model\" in the AI Chat settings" + detail + ".";
			case 413:
				return "This chat has grown too long to send. Start a new chat.";
			case 429:
				return "Anthropic's rate limit was hit. Try again in a minute" + detail + ".";
			case 500:
			case 502:
			case 503:
			case 529:
				return "Anthropic is overloaded or having trouble right now. Try again shortly.";
			default:
				return "Anthropic answered HTTP " + code + detail + ".";
		}
	}

	private static String string(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonPrimitive() ? e.getAsString() : null;
	}
}

package com.aichat;

